  if (o.carried || o.hang) return { turn: 0, move: 0, fire: false, jump: m.n % 2 === 0 };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 2 === 0 };

  const stuck = stuckTicks(o, m, 60);
  const boss = o.foes.find(f => f.k === 'boss' && f.awake);
  const near = o.foes.some(f => f.awake && f.d < 12);
  const fire = (!!o.aim.hit && m.n % 3 !== 0) || (m.n % 5 === 0 && near) || (!!boss && boss.d < 14 && m.n % 10 === 0);
  const slam = telegraphed(o, 4.5) || o.foes.some(f => f.awake && f.k === 'kitty' && f.d < 2.5 && Math.abs(f.dy) < 1.5);
  const out = (turn, move, jump, use) => ({
    turn: clampU(turn), move: clampU(move), fire, jump: !!jump, use: !!use, sel: 0,
  });

  if (boss && boss.d < 14 && o.floor === 5 && g.kind !== 'crane-step' && g.kind !== 'flag') {
    const ang = Math.atan2(boss.dy, boss.d);
    const useNow = o.inv.length > 0 && m.n - (m.u || -99) > 25;
    if (useNow) m.u = m.n;
    let move = boss.d > 9 ? 0.8 : boss.d < 6 ? -0.5 : 0.2;
    if (!boss.band && Math.abs(ang) > 0.15 && boss.d < 12) move = -0.6;
    if (move > 0 && o.drop.f < 2) move = 0;
    const weave = Math.floor(o.t / 3) % 2 ? 0.15 : -0.15;
    return out(steerTo(boss.b + weave, 2.5), move, slam, useNow);
  }

  const e = wrapA(Math.PI - o.yaw);
  if (g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2.5)) {
    if (g.kind === 'ladder-approach' && Math.abs(e) > 0.5 && g.d > 1) {
      return out(steerTo(g.b, 2.5), Math.abs(g.b) < 1 ? 0.5 : 0, slam);
    }
    return out(e * 3, Math.abs(e) < 0.5 ? 1 : 0, slam);
  }
  if (g.kind === 'lift' && g.d < 1.2) return out(steerTo(g.b, 2), 0, slam);

  const ramp = /stairs|spring|crane/.test(g.kind);
  if (stuck) {
    if (/stairs|crane/.test(g.kind)) return out(steerTo(g.b, 2.5), Math.abs(g.b) < 1 ? 1 : 0.3, m.n % 6 < 3);
    return out(Math.sin(m.n * 0.7), o.drop.f < 1.5 ? 0 : 0.8, true);
  }

  const heal = o.hp < 55 ? o.items.find(i => i.k === 'juice' && i.d < 8) : null;
  const tb = heal ? heal.b : g.b;
  const edge = !ramp && o.drop.f < 1.5;
  const hop = g.kind === 'crane-step' && g.d < 1.5 && o.ground;
  const move = edge || Math.abs(tb) >= 1.4 ? 0 : Math.abs(tb) < 0.9 ? 0.15 : 0.08;
  const car = o.foes.some(f => f.awake && f.k === 'car' && f.d < 6 && Math.abs(f.b) < 0.8 && /rev|charge/.test(f.st || ''));
  if (car) return out(steerTo(tb, 2.5), -0.7, slam || o.foes.some(f => f.k === 'car' && f.d < 3));
  return out(steerTo(tb, 2.5), move, hop || slam);
}

// Steady-fire climber: fires whenever foes are near, uses pickups on big threats, grabs nearby items when safe (juice when hurt)
function step(o, m) {
  const g = o.goal;
  m.n = (m.n || 0) + 1;
  if (o.dead) return {};
  const near = o.foes.some(f => f.awake && f.d < 10);
  const fire = !!o.aim.hit || (near && m.n % 2 === 0);
  // pickup use: big threat or crowd close and in front
  let pk = {};
  const si = o.inv.findIndex(i => i.n > 0 && i.k !== 'balloon');
  if (si >= 0) {
    const front = o.foes.filter(f => f.awake && f.d < 7 && Math.abs(f.b) < 0.6);
    const big = front.some(f => /golem|boss|car/.test(f.k) && f.d < 6);
    if (big || front.length >= 3) pk = { sel: si, use: m.n % 4 === 0 };
  }
  if (o.carried || o.hang) return { turn: 0, move: 0, fire: true, jump: m.n % 2 === 0 };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: true, jump: m.n % 2 === 0 };
  if (o.climbing || g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2)) {
    const e = wrapA(Math.PI - o.yaw);
    return { turn: clampU(e * 3), move: Math.abs(e) < 0.5 ? 1 : 0, fire, jump: false, ...pk };
  }
  const bw = o.foes.find(f => f.k === 'boss');
  if (bw && o.floor === 5 && g.kind !== 'crane-step' && g.kind !== 'flag') {
    const atk = /slam|wind|crouch|rev/.test(bw.st || '') && bw.d < 9;
    const mv = bw.d < 5 ? -0.8 : bw.d > 9 ? 0.8 : (bw.band ? 0 : -0.4);
    const swirl = bw.d < 9 && bw.d > 5 ? 0.15 : 0;
    return {
      turn: clampU(bw.b * 3 + swirl),
      move: Math.abs(bw.b) > 1.2 && mv > 0 ? 0 : mv,
      fire: true,
      jump: (atk || shotDanger(o, 3, 0.6)) && o.ground,
      ...pk,
    };
  }
  if (g.kind === 'lift' && g.d < 1.2) return { turn: steerTo(g.b, 2), move: 0, fire, jump: telegraphed(o, 4), ...pk };
  const hop = (g.kind === 'crane-step' && g.d < 2.5) || telegraphed(o, 6) || shotDanger(o, 3, 0.6);
  // dodge: back away from a winding-up foe in front of us
  const threat = o.foes.some(f => f.awake && f.d < 4 && Math.abs(f.b) < 1.2 && /slam|wind|crouch|rev|dive|throw/.test(f.st || ''));
  const stuck = stuckTicks(o, m, 30) && g.kind !== 'lift' && g.kind !== 'boss';
  if (stuck && !(m.esc > 0)) { m.esc = 15; m.dir = -(m.dir || 1); m.c = -30; }
  const edge = ledgeAhead(o, g);
  if (m.esc > 0) {
    m.esc--;
    return { turn: clampU(m.dir * 0.8), move: m.esc > 8 ? -0.7 : (edge ? 0 : 0.7), fire, jump: m.esc % 4 === 0 && o.ground, ...pk };
  }
  // item detour when calm
  const calm = !o.foes.some(f => f.awake && f.d < 4);
  let tb = g.b;
  const want = calm && o.shots.length === 0 && o.items.find(i =>
    Math.abs(i.dy) < 1.5 && (i.k === 'juice' ? (o.hp < 80 && i.d < 9) : i.d < 5));
  if (want && !edge) tb = want.b;
  const brisk = Math.abs(tb) < 1.4;
  const slow = o.foes.some(f => f.awake && f.d < 3);
  const springRun = g.kind === 'spring' && g.d < 2.5;
  const side = tb > 0 ? o.drop.r : o.drop.l;
  const mv = threat && !edge ? -0.5 : edge || (side < 1.2 && !springRun) ? 0 : springRun ? 0.5 : brisk ? (slow ? 0.08 : 0.15) : 0.05;
  const turn = springRun ? steerTo(g.b, 4) : clampU(tb * 3);
  return { turn, move: mv, fire, jump: hop && o.ground, ...pk };
}
